// src/report/verdicts.ts
var VERDICT_INFO = {
  verified: {
    meaning: "Direct evidence supports the claim, and nothing later invalidates it.",
    example: "npm test exited 0 after the last code edit."
  },
  contradicted: {
    meaning: "Evidence shows the claim is false.",
    example: 'The last npm test exited 1, but the agent said "all tests pass".'
  },
  stale: {
    meaning: "The claim was true at some point, but later changes broke the link.",
    example: "Tests passed at step 40, then src/parser.ts was edited at step 52 with no test run after."
  },
  unverified: {
    meaning: "There is no evidence either way.",
    example: '"Tests pass", but no test command ever ran.'
  },
  "needs-review": {
    meaning: "The claim is about behaviour that cannot be checked mechanically. A person must look. This is an honest answer, not a failure.",
    example: '"The dropdown now feels faster."'
  }
};

// src/commands/explain.ts
function explain(id) {
  const key = id.trim().toLowerCase().replace(/\s+/g, "-");
  if (VERDICTS.includes(key)) {
    const info = VERDICT_INFO[key];
    return `${key}

${info.meaning}

Example: ${info.example}
`;
  }
  if (FLAG_IDS.includes(key)) {
    const info = FLAG_INFO[key];
    return `${key} (${info.severity})
${info.title}

${info.explain}
`;
  }
  throw new ReceiptsError(
    `"${id}" is not a verdict or a flag.
Verdicts: ${VERDICTS.join(", ")}
Flags: ${FLAG_IDS.join(", ")}`,
    ExitCode.Usage
  );
}

// src/commands/hook.ts
import { execFileSync as execFileSync2 } from "node:child_process";
import { chmodSync, existsSync as existsSync9, mkdirSync as mkdirSync4, readFileSync as readFileSync6, writeFileSync as writeFileSync3 } from "node:fs";
import path18 from "node:path";
var MARKER = "Installed by Receipts";
function hookScript(failOn) {
  return `#!/bin/sh
# ${MARKER}. Blocks a push when the latest agent session in this repository
# has claims that are ${failOn.split(",").join(" or ")}. Remove this file to stop.
root="$(git rev-parse --show-toplevel)"
if command -v receipts >/dev/null 2>&1; then
  receipts check latest --repo "$root" --no-llm --format terminal --fail-on ${failOn}
else
  npx --yes github:sakshar2303/receipts check latest --repo "$root" --no-llm --format terminal --fail-on ${failOn}
fi
status=$?
if [ "$status" -eq 1 ]; then
  echo "receipts: push blocked. Fix the claims above, or push with --no-verify to skip this check."
  exit 1
fi
# Missing sessions or other errors never block a push.
exit 0
`;
}
async function installHook(options) {
  let hooksDir;
  try {
    hooksDir = execFileSync2("git", ["-C", options.cwd, "rev-parse", "--git-path", "hooks"], {
      encoding: "utf8"
    }).trim();
  } catch {
    throw new ReceiptsError(`${options.cwd} is not a git repository.`, ExitCode.Usage);
  }
  const hookPath = path18.resolve(options.cwd, hooksDir, "pre-push");
  if (existsSync9(hookPath) && !readFileSync6(hookPath, "utf8").includes(MARKER) && !options.force) {
    if (!options.confirm) {
      throw new ReceiptsError(
        `A pre-push hook already exists at ${hookPath}. Rerun with --force to replace it.`,
        ExitCode.Usage
      );
    }
    if (!await options.confirm(`A pre-push hook already exists at ${hookPath}. Replace it? [y/N] `)) {
      return `Left the existing hook at ${hookPath} unchanged.
`;
    }
  }
  mkdirSync4(path18.dirname(hookPath), { recursive: true });
  writeFileSync3(hookPath, hookScript(options.failOn));
  chmodSync(hookPath, 493);
  return `Installed a pre-push hook at ${hookPath}. Pushes stop when the latest session has ${options.failOn.split(",").join(" or ")} claims.
`;
}

